  const [yaStr, maStr, daStr] = a.split('-');
  const [ybStr, mbStr, dbStr] = b.split('-');

  const ya = Number(yaStr);
  const ma = Number(maStr);
  const da = Number(daStr);

  const yb = Number(ybStr);
  const mb = Number(mbStr);
  const db = Number(dbStr);

  const dateA = new Date(Date.UTC(ya, ma - 1, da));
  const dateB = new Date(Date.UTC(yb, mb - 1, db));

  const timeDiff = dateB - dateA;
  return Math.floor(timeDiff / (1000 * 60 * 60 * 24));
